import{_ as t}from"./chunks/slow-computations.cRfdC8wn.js";import{_ as o,o as i,c as a,aj as n}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"Slow computations","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"best-practices/slow-computations.md","filePath":"best-practices/slow-computations.md"}'),s={name:"best-practices/slow-computations.md"};function r(c,e,l,p,h,u){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="slow-computations" tabindex="-1">Slow computations <a class="header-anchor" href="#slow-computations" aria-label="Permalink to &quot;Slow computations&quot;">​</a></h1><p>On every change detection cycle, Angular synchronously:</p><ul><li>Evaluates all template expressions in all components, unless specified otherwise, based on that each component&#39;s detection strategy</li><li>Executes the <code>ngDoCheck</code>, <code>ngAfterContentChecked</code>, <code>ngAfterViewChecked</code>, and <code>ngOnChanges</code> lifecycle hooks. A single slow computation within a template or a lifecycle hook can slow down the entire change detection process because Angular runs the computations sequentially.</li></ul><h2 id="identifying-slow-computations" tabindex="-1">Identifying slow computations <a class="header-anchor" href="#identifying-slow-computations" aria-label="Permalink to &quot;Identifying slow computations&quot;">​</a></h2><p>You can identify heavy computations with Angular DevTools’ profiler. In the performance timeline, click a bar to preview a particular change detection cycle. This displays a bar chart, which shows how long the framework spent in change detection for each component. When you click a component, you can preview how long Angular spent evaluating its template and lifecycle hooks.</p><img alt="Angular DevTools profiler preview showing slow computation" src="'+t+'"><p>For example, in the preceding screenshot, the second recorded change detection cycle is selected. Angular spent over 573 ms on this cycle, with the most time spent in the <code>EmployeeListComponent</code>. In the details panel, you can see that Angular spent over 297 ms evaluating the template of the <code>EmployeeListComponent</code>.</p><h2 id="optimizing-slow-computations" tabindex="-1">Optimizing slow computations <a class="header-anchor" href="#optimizing-slow-computations" aria-label="Permalink to &quot;Optimizing slow computations&quot;">​</a></h2><p>Here are several techniques to remove slow computations:</p><ul><li><strong>Optimizing the underlying algorithm</strong>. This is the recommended approach. If you can speed up the algorithm that is causing the problem, you can speed up the entire change detection mechanism.</li><li><strong>Caching using pure pipes</strong>. You can move the heavy computation to a pure <a href="/guide/templates/pipes">pipe</a>. Angular reevaluates a pure pipe only if it detects that its inputs have changed, compared to the previous time Angular called it.</li><li><strong>Using memoization</strong>. <a href="https://en.wikipedia.org/wiki/Memoization" target="_blank" rel="noreferrer">Memoization</a> is a similar technique to pure pipes, with the difference that pure pipes preserve only the last result from the computation where memoization could store multiple results.</li><li><strong>Avoid repaints/reflows in lifecycle hooks</strong>. Certain <a href="https://web.dev/avoid-large-complex-layouts-and-layout-thrashing/" target="_blank" rel="noreferrer">operations</a> cause the browser to either synchronously recalculate the layout of the page or re-render it. Since reflows and repaints are generally slow, you want to avoid performing them in every change detection cycle.</li></ul><p>Pure pipes and memoization have different trade-offs. Pure pipes are an Angular built-in concept compared to memoization, which is a general software engineering practice for caching function results. The memory overhead of memoization could be significant if you invoke the heavy computation frequently with different arguments.</p>',11)]))}const f=o(s,[["render",r]]);export{g as __pageData,f as default};
